# Manual implementation of finding minimal edits
def find_minimal_edit(s_in, s_out):
    """Find the minimal change from s_in to s_out"""
    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # Strings are identical up to min length
        if len(s_in) == len(s_out):
            return None  # No change
        else:
            pos = min_len

    # Determine what to replace
    if len(s_in) > len(s_out):
        # Deletion case
        old_sub = s_in[pos]
        new_sub = ""
    elif len(s_in) < len(s_out):
        # Insertion case  
        old_sub = ""
        new_sub = s_out[pos]
    else:
        # Replacement case
        old_sub = s_in[pos]
        new_sub = s_out[pos]

    return (old_sub, new_sub, pos)

