# Let me carefully identify what can be replaced
inputs = ['fhy', 'hhhhjc', 'vajzch', 'jx', 'cf']
outputs = ['fbbhy', 'dvdvjc', 'vajzcbbh', 'jx', 'cf']

print("Analyzing what actually changes:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Let's see what parts of the input string are involved in the change
        # One approach: find longest common prefix/suffix
        min_len = min(len(inp), len(outp))

        # Find where they start differing
        prefix_len = 0
        for j in range(min_len):
            if inp[j] == outp[j]:
                prefix_len += 1
            else:
                break

        # Find where they end differing  
        suffix_len = 0
        for j in range(1, min_len + 1):
            if inp[-j] == outp[-j]:
                suffix_len += 1
            else:
                break

        print(f"  Common prefix: {prefix_len} chars")
        print(f"  Common suffix: {suffix_len} chars")
        print(f"  Change in middle: positions {prefix_len} to {len(inp)-suffix_len}")

# Now let's look for potential replace patterns
print("\nLooking for valid replace patterns:")

# Check for simple character replacements that might work
potential_patterns = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        # Look for character replacements that happen consistently
        for pos in range(min(len(inp), len(outp))):
            if pos < len(inp) and pos < len(outp) and inp[pos] != outp[pos]:
                old_char = inp[pos]
                new_char = outp[pos]
                potential_patterns.append((old_char, new_char, i))
                break  # Just take first difference for now

print("Potential single character replacements:")
for pat in potential_patterns:
    print(f"  '{pat[0]}' -> '{pat[1]}' (from example {pat[2]})")

